#include <stdio.h>
#include <string.h>

int main() {
    char s[10005], old[1005], rep[1005], res[20005];

    fgets(s, sizeof(s), stdin);
    fgets(old, sizeof(old), stdin);
    fgets(rep, sizeof(rep), stdin);

    old[strcspn(old, "\n")] = 0;
    rep[strcspn(rep, "\n")] = 0;

    int i = 0, j = 0;
    int len = strlen(old);

    while (s[i]) {
        if (strncmp(&s[i], old, len) == 0) {
            strcpy(&res[j], rep);
            j += strlen(rep);
            i += len;
        } else {
            res[j++] = s[i++];
        }
    }

    res[j] = '\0';
    printf("%s", res);

    return 0;
}

