#include <stdio.h>
#include <ctype.h>
#include <limits.h>

int main() {
    char s[10005];
    fgets(s, sizeof(s), stdin);

    int i = 0, sign = 1;
    long res = 0;

    while (s[i] == ' ') i++;

    if (s[i] == '+' || s[i] == '-') {
        if (s[i] == '-') sign = -1;
        i++;
    }

    while (isdigit(s[i])) {
        res = res * 10 + (s[i] - '0');

        if (sign * res > INT_MAX) {
            printf("%d", INT_MAX);
            return 0;
        }
        if (sign * res < INT_MIN) {
            printf("%d", INT_MIN);
            return 0;
        }

        i++;
    }

    printf("%ld", sign * res);

    return 0;
}

