  Scanner sc=new Scanner(System.in);
  String s=sc.nextLine();
  int n=s.length(),res=0;
  boolean[][] dp=new boolean[n][n];
  for(int g=0;g<n;g++){
   for(int i=0;i+g<n;i++){
    int j=i+g;
    if(g==0) dp[i][j]=true;
    else if(g==1) dp[i][j]=(s.charAt(i)==s.charAt(j));
    else dp[i][j]=(s.charAt(i)==s.charAt(j)&&dp[i+1][j-1]);
    if(dp[i][j]) res++;
   }
  }
