char stackStr[100][1000];
int stackNum[100];
int top = -1;

int main() {
    char s[1000];
    scanf("%s", s);

    char curr[1000] = "";
    int num = 0;

    for (int i = 0; s[i]; i++) {
        if (isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
        } else if (s[i] == '[') {
            top++;
            stackNum[top] = num;
            strcpy(stackStr[top], curr);
            num = 0;
            curr[0] = '\0';
        } else if (s[i] == ']') {
            char temp[1000];
            strcpy(temp, stackStr[top]);
            for (int j = 0; j < stackNum[top]; j++) {
                strcat(temp, curr);
            }
            strcpy(curr, temp);
            top--;
        } else {
            int len = strlen(curr);
            curr[len] = s[i];
            curr[len + 1] = '\0';
        }
    }

    printf("%s", curr);

    return 0;
}

